properties.query:
// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(15m) and ingestion_time() <= now();
CowrieNew
| where eventid =~ "cowrie.command.input" and input matches regex "^\\s*(enable|system|shell|linuxshell|sh)\\s*$"
// One alert per source IP
| summarize Matches = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by src_ip
